pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fundAmount, uint8 nonce) public {
        vm.assume(fundAmount > 0 && fundAmount <= 100 ether);
        // fund the contract with some ether to observe balance after destruction
        address donor = address(uint160(uint256(keccak256(abi.encodePacked(nonce)))));
        vm.deal(donor, fundAmount);
        vm.prank(donor);
        (bool ok, ) = address(c).call{value: fundAmount}("");
        require(ok, "funding failed");

        // owner calls sudicideAnyone
        vm.prank(c.smartfix_owner());
        try c.sudicideAnyone() { } catch { }

        // the destroyed contract must have zero balance
        assertTrue(address(c).balance == 0);
    }
}

