pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 value) public {
        // bound value to a small non-zero amount to keep funding manageable
        uint256 fundAmount = uint256(value) + 1;
        // only the owner may call sudicideAnyone, so we use the address that deployed the contract
        address owner = address(this);
        vm.deal(owner, fundAmount);
        vm.prank(owner);
        // fund the contract by sending ether directly
        payable(address(c)).transfer(fundAmount);
        uint256 contractBalanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = owner.balance;
        vm.prank(owner);
        // the call should succeed; a revert means the test is not applicable (owner is always msg.sender here)
        c.sudicideAnyone();
        // After selfdestruct, code is destroyed, balance goes to designated recipient.
        // The reference sends to msg.sender (owner), so owner balance should increase by contractBalanceBefore.
        // The bug sends to smartfix_owner (also the same owner here), but the difference is observable
        // because in the reference the balance increase equals contractBalanceBefore; in the bug,
        // the destroyed address may still show balance (but actually selfdestruct sends the full balance).
        // The key observable: after selfdestruct, address(c).balance is 0.
        // However, the bug still selfdestructs, so the balance at destroyed address is also 0.
        // The real difference is that the recipient of the remaining ETH differs.
        // Since both reference and bug destroy the contract, we check the recipient balance.
        // But here owner == smartfix_owner, so the balance increase would be identical!
        // To observe the difference, we need the caller (msg.sender) to differ from smartfix_owner.
        // So we change ownership first.
    }
}

