pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, uint256 initialBalance) public {
        // Restrict to admissible domain: non-zero smartfix_owner (deployer) and positive balance
        vm.assume(attacker != address(this));
        initialBalance = bound(initialBalance, 1 ether, 100 ether);

        // Fund the contract
        vm.deal(address(c), initialBalance);

        // Record initial balances
        uint256 callerBalanceBefore = address(this).balance;
        uint256 contractBalanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = attacker.balance;

        // attacker calls sudicideAnyone (should revert because attacker != smartfix_owner)
        // We need owner to call; smartfix_owner is deployer (this contract).
        // The bug manifests when the caller IS smartfix_owner but selfdestruct sends to smartfix_owner instead of caller.
        // Since caller == smartfix_owner, we test that the caller receives the contract balance.
        // Use vm.prank(this) since this contract is smartfix_owner.
        vm.prank(address(this));
        bool ok = true;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }

        if (ok) {
            uint256 callerBalanceAfter = address(this).balance;
            uint256 contractBalanceAfter = address(c).balance;
            assertTrue(callerBalanceAfter + contractBalanceAfter == callerBalanceBefore + contractBalanceBefore);
        }
    }
}

