import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr, uint256 amount) public {
        vm.assume(addr != address(0));
        vm.assume(amount > 0);
        vm.deal(addr, amount);
        vm.prank(addr);
        uint256 priorBalanceSender = addr.balance;
        uint256 priorBalanceOwner = c.smartfix_owner().balance;
        uint256 priorBalanceContract = address(c).balance;
        c.sudicideAnyone{value: amount}();
        // After selfdestruct, the caller (addr) should receive all funds that were in the contract.
        // The contract's code is destroyed, so balance is inaccessible; assert that the caller's
        // balance increased by the contract's prior balance, not the owner's.
        uint256 afterBalanceSender = addr.balance;
        uint256 afterBalanceOwner = c.smartfix_owner().balance;
        // The contract's Ether must be sent to the caller.
        assertTrue(afterBalanceSender - priorBalanceSender == priorBalanceContract + amount);
    }
}
